import { Module } from "@medusajs/framework/utils"
import EyewearModuleService from "./service"

export const EYEWEAR_MODULE = "eyewear"

/**
 * Emitted by the eyewear workflows (not auto-generated by MedusaService) so the
 * payload always  carries the linked `product_id` directly. The automatic
 * `eyewear_details.created/updated/deleted` events only carry the
 * EyewearDetails id, and delete uses a hard delete, so there'd be nothing left
 * to resolve the product from by the time a consumer reads the event.
 */
export const EYEWEAR_SEARCH_REINDEX_EVENT = "eyewear_details.reindex"

export default Module(EYEWEAR_MODULE, {
  service: EyewearModuleService,
})
